import { lookupOrder, markOrderAsRefunded, type Order } from './order.service.js';
import { err, ok, type Result } from '../kernel/result.js';

export interface RefundedOrder {
  readonly id: string;
  readonly amount: number;
  readonly refundedAt: Date;
}

export function refundOrder(orderId: string): Result<RefundedOrder, string> {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return err(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    return err(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    return err(`Order ${orderId} total (${order.total}) is below minimum refund amount of 10`);
  }

  markOrderAsRefunded(orderId);

  return ok({
    id: orderId,
    amount: order.total,
    refundedAt: new Date(),
  });
}

